{
  "name": "search_documents",
  "description": "Search the internal knowledge base. Use for questions about company policy, products, or past decisions. Do NOT use for real-time data (use web_search) or calculations.",
  "parameters": {
    "query": {
      "type": "string",
      "description": "A standalone keyword search phrase (e.g. 'refund policy enterprise'). Not a full question."
    },
    "top_k": {
      "type": "integer",
      "description": "Number of results, 1-10. Use 3 for narrow fact lookups, 8+ for research tasks.",
      "default": 5
    },
    "date_after": {
      "type": "string",
      "description": "Optional ISO date filter, e.g. '2026-01-01'. Only set when the user asks about recent info."
    }
  }
}
